// multiAggregatorAssertStatsZeroOnError asserts Stats returns the zero for every result alongside any error.
func multiAggregatorAssertStatsZeroOnError(
	tb testing.TB,
	m MultiAggregator,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, got2, err := m.Stats(ctx)
	if err == nil {
		tb.Skip("Stats answered for a cancelled context, so this check has no error to inspect")
	}

	var zero int
	if got != zero {
		tb.Errorf("Stats must return the zero int alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
	var zero2 int
	if got2 != zero2 {
		tb.Errorf("Stats must return the zero int alongside an error: got %+v, want %+v (err %v)",
			got2, zero2, err)
	}
}

